import { listProjectScopedRemoteToolNames, } from "../../tool/index.js";
import { resolveRuntimeSkillSelectorSnapshotForAgent, } from "../runtime/skill-metadata.js";
import { selectProviderCompatibleToolNames } from "../runtime/provider-tool-compat.js";
import { flattenSystemInstructions, withRuntimeToolInventory } from "../runtime/tool-inventory.js";
import { TOOL_SEARCH_TOOL_NAME } from "../runtime/tool-exposure.js";
import { isLoadSkillToolName } from "../runtime/skill-policy-enforcement.js";
import { isRuntimeProviderSchemaHiddenTool } from "../runtime/local-tool.js";
import { resolveHostedRuntimeSkillLoaderToolName } from "./cloud-runtime-system-messages.js";
import { assertResolvedSkillSelector, createNoneSkillSelectorSnapshot, skillSelectorPolicyToSelector, } from "../../skill/selector.js";
import { compareStrings } from "../../utils/compare.js";
/** Fetch default hosted project steering helper. */
export async function fetchDefaultHostedProjectSteering(input) {
    const projectId = input.projectId;
    if (!projectId) {
        return { instructions: "", skills: [] };
    }
    const fetchSteering = async () => {
        const [instructions, skills] = await Promise.all([
            input.fetchProjectInstructions({
                projectId,
                authToken: input.authToken,
                branchId: input.branchId,
            }),
            input.fetchSkills({
                projectId,
                authToken: input.authToken,
                branchId: input.branchId,
            }),
        ]);
        return {
            instructions,
            skills,
        };
    };
    if (!input.trace) {
        return await fetchSteering();
    }
    return await input.trace(input.traceOperationName ?? "agent.fetchProjectSteering", fetchSteering);
}
function getActiveProjectId(taskContext) {
    return taskContext.projectId || null;
}
function getActiveBranchId(taskContext) {
    return taskContext.branchId ?? null;
}
async function fetchProjectInstructionsWithFallback(input) {
    try {
        return await input.options.fetchProjectInstructions({
            projectId: input.projectId,
            authToken: input.taskContext.authToken,
            branchId: input.branchId,
        });
    }
    catch (error) {
        input.options.logger?.error("Refreshing project instructions failed during hosted runtime steering update", {
            projectId: input.projectId,
            branchId: input.branchId,
            error: error instanceof Error ? error.message : String(error),
        });
        return input.initialProjectInstructions;
    }
}
async function fetchSkillsWithFallback(input) {
    try {
        return await input.options.fetchSkills({
            projectId: input.projectId,
            authToken: input.taskContext.authToken,
            branchId: input.branchId,
        });
    }
    catch (error) {
        input.options.logger?.error("Refreshing skills failed during hosted runtime steering update", {
            projectId: input.projectId,
            branchId: input.branchId,
            error: error instanceof Error ? error.message : String(error),
        });
        return input.initialSkills;
    }
}
function resolveRefreshedSkillSnapshot(input) {
    if (!input.policy) {
        if (input.selector === false ||
            (Array.isArray(input.selector) && input.selector.length === 0)) {
            return createNoneSkillSelectorSnapshot();
        }
        return resolveRuntimeSkillSelectorSnapshotForAgent({
            skills: input.skills,
            agentId: input.agentId,
            selector: Array.isArray(input.selector) ? [...input.selector] : input.selector,
        });
    }
    if (input.policy.kind === "all-visible") {
        return resolveRuntimeSkillSelectorSnapshotForAgent({
            skills: input.skills,
            agentId: input.agentId,
            selector: input.policy.source === "true" ? true : undefined,
        });
    }
    if (input.policy.kind === "none") {
        return createNoneSkillSelectorSnapshot(input.policy);
    }
    return resolveRuntimeSkillSelectorSnapshotForAgent({
        skills: input.skills,
        agentId: input.agentId,
        selector: skillSelectorPolicyToSelector(input.policy),
    });
}
function filterProviderVisibleLocalToolNames(input) {
    return input.toolNames.filter((toolName) => !isRuntimeProviderSchemaHiddenTool(input.runtimeTools[toolName]));
}
/** Create default hosted project steering refresh. */
export function createDefaultHostedProjectSteeringRefresh(options) {
    return async (input) => {
        const projectId = getActiveProjectId(input.taskContext);
        const branchId = getActiveBranchId(input.taskContext);
        const initialProjectInstructions = input.liveProjectSteering.initialProjectInstructions ?? "";
        const initialSkills = input.liveProjectSteering.initialSkills ?? [];
        const [projectInstructions, skills, remoteToolNames] = await Promise.all([
            projectId
                ? fetchProjectInstructionsWithFallback({
                    options,
                    taskContext: input.taskContext,
                    projectId,
                    branchId,
                    initialProjectInstructions,
                })
                : Promise.resolve(""),
            projectId
                ? fetchSkillsWithFallback({
                    options,
                    taskContext: input.taskContext,
                    projectId,
                    branchId,
                    initialSkills,
                })
                : Promise.resolve([]),
            listProjectScopedRemoteToolNames(input.toolAssembly.remoteToolSources, {
                sourceIntegrationPolicy: input.toolAssembly.sourceIntegrationPolicy,
                projectId,
                projectScopedRemoteToolOptions: options.projectScopedRemoteToolOptions,
            }),
        ]);
        const skillSelectorSnapshot = resolveRefreshedSkillSnapshot({
            skills,
            agentId: input.liveProjectSteering.agent.id,
            selector: input.liveProjectSteering.agent.skills,
            policy: input.taskContext.skillSelectorPolicy ??
                input.liveProjectSteering.skillSelectorPolicy,
        });
        assertResolvedSkillSelector(skillSelectorSnapshot);
        input.taskContext.availableSkillIds = skillSelectorSnapshot.allowedSkillIds;
        input.taskContext.skillSelectorPolicy = skillSelectorSnapshot.policy;
        input.taskContext.skillSourcePaths =
            Object.keys(skillSelectorSnapshot.skillSourcePaths).length > 0
                ? skillSelectorSnapshot.skillSourcePaths
                : undefined;
        const providerVisibleLocalToolNames = filterProviderVisibleLocalToolNames({
            toolNames: input.toolAssembly.localToolNames,
            runtimeTools: input.toolAssembly.runtimeTools,
        });
        const allToolNames = [
            ...new Set([
                ...providerVisibleLocalToolNames,
                ...remoteToolNames,
                ...input.toolAssembly.providerToolNames,
            ]),
        ].sort(compareStrings);
        const toolNames = selectProviderCompatibleToolNames(allToolNames, {
            ...(input.toolAssembly.toolSchemaTarget ?? { model: input.taskContext.model }),
            reservedToolSlots: input.toolAssembly.reservedToolSlots,
            requiredToolNames: providerVisibleLocalToolNames,
        });
        const bootstrapToolNames = (input.toolAssembly.modelVisibleToolNames ?? toolNames).filter(isLoadSkillToolName);
        const selectedBootstrapToolNames = new Set(bootstrapToolNames);
        const hasDeferredTools = toolNames.some((toolName) => {
            if (selectedBootstrapToolNames.has(toolName))
                return false;
            return !isRuntimeProviderSchemaHiddenTool(input.toolAssembly.runtimeTools[toolName]);
        });
        const modelVisibleToolNames = input.toolAssembly.toolLoadingMode === "deferred"
            ? [
                ...bootstrapToolNames,
                ...(hasDeferredTools ? [TOOL_SEARCH_TOOL_NAME] : []),
            ].sort(compareStrings)
            : toolNames;
        input.taskContext.availableToolNames = modelVisibleToolNames;
        const promptSkills = modelVisibleToolNames.some(isLoadSkillToolName)
            ? skillSelectorSnapshot.definitions
            : [];
        const refreshedInstructions = options.buildInstructions({
            agentConfig: input.liveProjectSteering.agent,
            projectId,
            branchId,
            environmentContext: input.liveProjectSteering.environmentContext,
            instructions: projectInstructions,
            skills: promptSkills,
            availableToolNames: modelVisibleToolNames,
            skillLoaderToolName: resolveHostedRuntimeSkillLoaderToolName(modelVisibleToolNames),
        });
        const instructionsWithToolInventory = withRuntimeToolInventory(refreshedInstructions, modelVisibleToolNames);
        return typeof refreshedInstructions === "string"
            ? flattenSystemInstructions(instructionsWithToolInventory)
            : instructionsWithToolInventory;
    };
}
